create table examenes_escolares (date date, deleted boolean not null, created_date timestamp(6), id bigint not null, id_docente bigint, id_materia bigint, id_periodo_lectivo bigint, id_tipo_examen bigint, last_modified_date timestamp(6), created_by varchar(255), description varchar(255), last_modified_by varchar(255), name varchar(255), primary key (id));
