create table tipo_examen (deleted boolean not null, created_date timestamp(6), id bigint not null, last_modified_date timestamp(6), school_exam_id bigint, created_by varchar(255), description varchar(255), last_modified_by varchar(255), name varchar(255), primary key (id));
